#ifdef X4_UI49_CAPTURE
static bool pseudo_for_test;
static char pseudo_texts[2][X4_TR_ALL_COUNT][1024];

void x4_lang_pseudo_for_test(bool enabled)
{
    pseudo_for_test = enabled;
}

static const char *pseudo_text(enum X4TextId id, const char *text)
{
    char *out = pseudo_texts[current_lang == X4_LANG_EN][id];
    const size_t len = strlen(text);
    if (!len || len + (len * 35 + 99) / 100 >= sizeof(pseudo_texts[0][0])) return text;
    if (out[0]) return out;
    const char filler[] = " extra words";
    memcpy(out, text, len);
    const size_t extra = (len * 35 + 99) / 100;
    for (size_t i = 0; i < extra; ++i) out[len + i] = filler[i % (sizeof(filler) - 1)];
    out[len + extra] = 0;
    return out;
}
#endif

const char *x4_tr_for_lang(enum X4Lang language, enum X4TextId id)
{
    static const char *const *const tables[X4_LANG_COUNT] = {
        table_es, table_en, table_pt_br, table_fr, table_it, table_de,
    };
    if ((unsigned)id >= X4_TR_ALL_COUNT) return "";
    if ((unsigned)language >= X4_LANG_COUNT) language = X4_LANG_EN;
    const char *text = tables[language][id];
    if (!text) text = table_en[id];
    return text ? text : "";
}

const char *x4_tr(enum X4TextId id)
{
    const char *text = x4_tr_for_lang(current_lang, id);
#ifdef X4_UI49_CAPTURE
    if (pseudo_for_test && (unsigned)id < X4_TR_ALL_COUNT) return pseudo_text(id, text);
#endif
    return text;
}

const char *x4_tr_count(unsigned count, enum X4TextId singular, enum X4TextId plural)
{
    return x4_tr(count == 1 ? singular : plural);
}

int x4_lang_is_cloud_unavailable(int error, int http_status, uint32_t xerr,
    const char *offering, const char *stage)
{
    if (xerr != 0) return 0;
    int is_4xx = (http_status >= 400 && http_status < 500);
    int is_xbox_offer_err = (error == -2010 /* X4_AUTH_E_XBOX */ || error == 0);
    int not_other_stage = (!stage || !stage[0] || !strcmp(stage, "Xbox Cloud Gaming rechazo la cuenta"));
    int is_second_offer = (!offering || !offering[0] || !strcmp(offering, "xgpuwebf2p"));
    return (is_4xx && is_xbox_offer_err && not_other_stage && is_second_offer) ? 1 : 0;
}

const char *x4_lang_catalog_error_msg(int error, int http_status, uint32_t xerr,
    const char *offering, const char *stage, char *buf, unsigned cap)
{
    if (xerr != 0) {
        if (xerr == 2148916233u) return x4_tr(X4_TR_XSTS_NO_PROFILE);
        if (xerr == 2148916235u) return x4_tr(X4_TR_XSTS_UNAVAILABLE_COUNTRY);
        if (xerr == 2148916236u || xerr == 2148916237u) return x4_tr(X4_TR_XSTS_AGE_VERIFICATION);
        if (xerr == 2148916238u) return x4_tr(X4_TR_XSTS_CHILD_ACCOUNT);
        if (buf && cap > 0) {
            snprintf(buf, cap, "%s (Xbox 0x%08X)", x4_tr(X4_TR_CAT_ERROR), xerr);
            return buf;
        }
        return x4_tr(X4_TR_CAT_ERROR);
    }
    /* Both offerings (xgpuweb and xgpuwebf2p) rejected with 4xx and xerr == 0 */
    if (x4_lang_is_cloud_unavailable(error, http_status, xerr, offering, stage) && buf && cap > 0) {
        snprintf(buf, cap, x4_tr(X4_TR_CLOUD_UNAVAILABLE_FMT), http_status);
        return buf;
    }
    return NULL;
}

