static const char *stage_translation(size_t index, enum X4Lang language)
{
    switch (language) {
    case X4_LANG_ES: return stage_map[index].display_es ? stage_map[index].display_es : stage_map[index].es;
    case X4_LANG_PT_BR: return stage_map[index].pt_br;
    case X4_LANG_FR: return stage_map[index].fr;
    case X4_LANG_IT: return stage_map[index].it;
    case X4_LANG_DE: return stage_map[index].de;
    default: return stage_map[index].en;
    }
}

const char *x4_tr_stage(const char *stage)
{
    if (!stage || !stage[0]) return "";
    if (!strcmp(stage, X4_STAGE_PLAY_ENTITLEMENT))
        return x4_tr(X4_TR_50_STAGE_PLAY_ENTITLEMENT);
    if (!strcmp(stage, X4_STAGE_EARLY_XBOX_CLOSE))
        return x4_tr(X4_TR_50_STAGE_EARLY_XBOX_CLOSE);
    if (!strcmp(stage, X4_STAGE_SERVER_GAME_CLOSED))
        return x4_tr(X4_TR_50_STAGE_SERVER_GAME_CLOSED);
    if (!strcmp(stage, X4_STAGE_SERVER_STREAMING_TIME))
        return x4_tr(X4_TR_50_STAGE_SERVER_STREAMING_TIME);
    for (size_t i = 0; i < sizeof(stage_map) / sizeof(stage_map[0]); ++i) {
        if (!strcmp(stage, stage_map[i].es)) return stage_translation(i, current_lang);
    }
    if (!strncmp(stage, X4_STAGE_PLAY_FAILED_PREFIX, sizeof(X4_STAGE_PLAY_FAILED_PREFIX) - 1)) {
        static char play_stage[96];
        (void)snprintf(play_stage, sizeof(play_stage), x4_tr(X4_TR_50_STAGE_PLAY_FAILED_FMT),
            stage + sizeof(X4_STAGE_PLAY_FAILED_PREFIX) - 1);
        return play_stage;
    }
    /* HTTP stages are wrapped into a public snapshot as "HTTPS: <stage>".
     * Translate the inner fixed literal; never change the HTTP state itself. */
    if (!strncmp(stage, "HTTPS: ", 7)) {
        static char http_stage[160];
        const char *inner = stage + 7;
        for (size_t i = 0; i < sizeof(stage_map) / sizeof(stage_map[0]); ++i) {
            if (!strcmp(inner, stage_map[i].es)) {
                snprintf(http_stage, sizeof(http_stage), "HTTPS: %s", stage_translation(i, current_lang));
                return http_stage;
            }
        }
        return stage;
    }
    const char game_closed[] = "Xbox cerró la sesión: el juego se cerró";
    if (!strncmp(stage, game_closed, sizeof(game_closed)-1)) {
        static char game_stage[160];
        snprintf(game_stage,sizeof(game_stage),x4_tr(X4_TR_50_STAGE_GAME_CLOSED_FMT),
            stage+sizeof(game_closed)-1);
        return game_stage;
    }
    const char closed_prefix[] = "Xbox cerró la sesión: ";
    if (!strncmp(stage, closed_prefix, sizeof(closed_prefix)-1)) {
        static char closed_stage[160];
        snprintf(closed_stage, sizeof(closed_stage), x4_tr(X4_TR_50_STAGE_CLOSED_FMT),
            stage + sizeof(closed_prefix)-1);
        return closed_stage;
    }
    const char lost_prefix[] = "Se perdió la conexión con el servidor de Xbox: ";
    if (!strncmp(stage, lost_prefix, sizeof(lost_prefix)-1)) {
        static char lost_stage[160];
        snprintf(lost_stage, sizeof(lost_stage), x4_tr(X4_TR_50_STAGE_LOST_FMT),
            stage + sizeof(lost_prefix)-1);
        return lost_stage;
    }
    const char es_prefix[] = "Xbox está preparando el juego… ";
    size_t es_pfx_len = strlen(es_prefix);
    if (!strncmp(stage, es_prefix, es_pfx_len)) {
        static char dynamic_stage[128];
        snprintf(dynamic_stage, sizeof(dynamic_stage), x4_tr(X4_TR_50_STAGE_PREPARING_FMT), stage + es_pfx_len);
        return dynamic_stage;
    }
    return stage;
}

#if !X4_PUBLIC
const char *x4_lang_lab_remb(enum X4LabRembText id)
{
    static const char *const es[X4_LAB_REMB_TEXT_COUNT] = {
        [X4_LAB_REMB_TITLE] = "Aviso de ancho de banda (REMB)",
        [X4_LAB_REMB_FIXED_TITLE] = "Límite fijo (REMB)",
        [X4_LAB_REMB_FIXED] = "Fijo",
        [X4_LAB_REMB_ADAPTIVE] = "Adaptable",
        [X4_LAB_REMB_HELP] = "Se aplica en la próxima partida si Xbox admite REMB.",
        [X4_LAB_REMB_FIXED_HELP] = "Se usa solo en modo Fijo."
    };
    static const char *const en[X4_LAB_REMB_TEXT_COUNT] = {
        [X4_LAB_REMB_TITLE] = "Bandwidth feedback (REMB)",
        [X4_LAB_REMB_FIXED_TITLE] = "Fixed limit (REMB)",
        [X4_LAB_REMB_FIXED] = "Fixed",
        [X4_LAB_REMB_ADAPTIVE] = "Adaptive",
        [X4_LAB_REMB_HELP] = "Applies to the next game if Xbox supports REMB.",
        [X4_LAB_REMB_FIXED_HELP] = "Used only in Fixed mode."
    };
    if ((unsigned)id >= X4_LAB_REMB_TEXT_COUNT) return "";
    return x4_lang_current() == X4_LANG_ES ? es[id] : en[id];
}

const char *x4_lang_lab_vsync_t27(int help)
{
    if(x4_lang_current()!=X4_LANG_ES)
        return help?"Enables VSync at 30 fps and disables it at 60 fps for lower delay.":
            "T27 automatic (no VSync at 60 fps)";
    return help?"Activa VSync a 30 fps y lo quita a 60 fps para reducir el retraso.":
        "Automática T27 (sin VSync a 60)";
}
#endif
